  insert into public.opportunities (brand_id, title, application_url, source_url, status, opportunity_type) values (bid, 'Astrid & You Creator Community (own program)', null, null, 'unverified', 'ugc');
  insert into public.brand_evidence (brand_id, source_url, source_type, evidence_type, evidence_summary, confidence, last_checked_at) values (bid, 'https://www.astridandmiyu.com/en-us/pages/astrid-and-you', 'brand_page', 'affiliate_program', 'The brand''s own Astrid & You page (fetched) advertises ''Up to 15% commission'' through a personal affiliate link. The structure is tiered: Chapters 1-2 earn points for orders placed through the link, and from Chapter 3 those points turn into cash commission (per the brand''s own help centre). ''Up to 15%'' is a rate ceiling with no published floor, so commission_rate is recorded as null. Entry requires age 18+, UK base (more regions coming), a public account and 1,000+ followers on Instagram or TikTok. No fetched source states any earnings cap, so commission_cap is unknown.', 'verified', now());
