  insert into public.brand_scores (brand_id, niche_fit, ugc_evidence, compensation, contact_access, opportunity_availability, credibility, explanation) values (bid, 25, 17, 11, 10, 6, 5, '["Contemporary stacking and piercing jewelry is a strong niche for fashion and beauty creators.", "A dedicated own-brand creator community built around UGC, with featured-content spotlights and event invites.", "Only an ''up to 15%'' ceiling is published and early chapters earn points before cash commission unlocks at Chapter 3, so the rate is honestly null; no earnings cap is stated, so the cap stays unknown.", "A direct application route on the brand''s own site, plus a parallel Rakuten program at a reported 6%.", "Application is open but gated: UK-based, 18+, public account and 1,000+ followers required.", "Established London jewelry brand founded in 2012 with a large retail and social presence."]'::jsonb);
