  insert into public.brand_evidence (brand_id, source_url, source_type, evidence_type, evidence_summary, confidence, last_checked_at) values (bid, 'https://www.charlestyrwhitt.com/us/affiliate-programme-new/affiliate-programme.html', 'brand_page', 'affiliate_program', 'The brand''s own affiliate page (fetched) states ''Up to 9% commission for new customer orders and 2% for existing customer orders'', confirms the USA programme runs through Commission Junction, offers a dedicated affiliate manager, and publishes the contact email affiliates@ctshirts.co.uk. Because the published structure splits by customer type with an ''up to'' ceiling on new orders, no single rate applies, so commission_rate is recorded as null with the full structure documented here. No fetched source states any earnings cap, so commission_cap is unknown.', 'verified', now());
  insert into public.brand_scores (brand_id, niche_fit, ugc_evidence, compensation, contact_access, opportunity_availability, credibility, explanation) values (bid, 23, 10, 11, 13, 8, 5, '["Classic menswear - shirts, tailoring, shoes - serves menswear and professional-style creators.", "A long-running affiliate programme, though oriented more to publishers than UGC creators.", "The brand publishes its structure (up to 9% on new-customer orders, 2% on existing) but no single rate, so the rate is honestly null; no earnings cap is stated, so the cap stays unknown.", "A partnerships email is published on the brand''s own affiliate page, plus a CJ application route and a named affiliate manager.", "Open application through CJ Affiliate, subject to site approval by the brand.", "Established British menswear retailer with global stores and e-commerce."]'::jsonb);
  insert into public.brands (name, website, description, country, status) values ('Timbuk2', 'https://www.timbuk2.com', 'San Francisco bag brand founded in 1989, known for messenger bags, backpacks and travel luggage built for urban and travel use. Its affiliate program runs through Pepperjam (Ascend).', 'United States', 'published') returning id into bid;
