  insert into public.brand_evidence (brand_id, source_url, source_type, evidence_type, evidence_summary, confidence, last_checked_at) values (bid, 'https://affi.io/m/timbuk2', 'affiliate_network', 'affiliate_program', 'Timbuk2''s affiliate program agreement (fetched) requires affiliates to join Pepperjam and states that commission rates are set inside the Pepperjam program rather than published in the terms. Third-party reports are low and conflicting - affjumbo lists 1% and Shopper reports 1.44-2.55% - so commission_rate is recorded as null with the reports documented here. No fetched source states any earnings cap, so commission_cap is unknown.', 'publicly_reported', now());
  insert into public.brand_scores (brand_id, niche_fit, ugc_evidence, compensation, contact_access, opportunity_availability, credibility, explanation) values (bid, 25, 11, 6, 8, 7, 5, '["Messenger bags, backpacks and luggage are core gear for travel and everyday-carry creators.", "A long-established bag brand with a network affiliate program, though creator-specific activity is modest.", "Rates are not published in the program terms and third-party reports are low and conflicting (1% vs 1.44-2.55%), so the rate is honestly null; no earnings cap is stated, so the cap stays unknown.", "Applications run through the Pepperjam program; no public brand partnerships email was found.", "Open application through Pepperjam, subject to network approval.", "Iconic San Francisco bag maker operating since 1989."]'::jsonb);
  insert into public.brands (name, website, description, country, status) values ('Snake River Farms', 'https://snakeriverfarms.com', 'Premium American Wagyu beef and Kurobuta pork brand (part of Agri Beef, founded 1968). Its own affiliates page publishes a 10% commission on all sales with a 30-day cookie, product review opportunities, monthly sales incentives and dedicated affiliate managers, and its signup routes to Impact; the page explicitly recruits content creators (''We are looking for content creators to share about our delicious Wagyu Beef''). Older directory listings citing 7% via ShareASale appear to predate the current Impact terms and are documented as a conflict. No cap statement or creator count is published, so cap and saturation are unknown.', 'United States', 'published') returning id into bid;
  insert into public.brand_categories (brand_id, category_id, is_primary) values (bid, (select id from public.categories where slug = 'food-drink'), true);
  insert into public.brand_contacts (brand_id, contact_type, email, contact_url, source_url, verification_status, last_verified_at) values (bid, 'creator_application', null, 'https://snakeriverfarms.com/pages/affiliates', 'https://snakeriverfarms.com/pages/affiliates', 'verified', now());
  insert into public.affiliate_programs (brand_id, network, commission_rate, commission_notes, application_url, status, last_checked_at) values (bid, 'Impact', 10, 'Commission cap: not stated in any published source found — needs review. Creator saturation: unknown (see evidence). Rate as reported by https://snakeriverfarms.com/pages/affiliates.', 'https://snakeriverfarms.com/pages/affiliates', 'needs_review', now());
  insert into public.opportunities (brand_id, title, application_url, source_url, status, opportunity_type) values (bid, 'Snake River Farms Affiliate Program — 10% on all sales via Impact, 30-day cookie, creator recruitment on the brand''s own page', 'https://snakeriverfarms.com/pages/affiliates', 'https://snakeriverfarms.com/pages/affiliates', 'unverified', 'ugc');
  insert into public.brand_evidence (brand_id, source_url, source_type, evidence_type, evidence_summary, confidence, last_checked_at) values (bid, 'https://snakeriverfarms.com/pages/affiliates', 'official_site', 'affiliate', 'Snake River Farms'' own affiliates page, fetched in full: ''10% Commission,'' ''30 Day Cookie Duration,'' product review opportunities, monthly sales incentives and dedicated affiliate managers; ''10% commission paid on all sales''; the ''Sign up now!'' link routes to app.impact.com, confirming the Impact network; and the FAQ states ''We are looking for content creators to share about our delicious Wagyu Beef, Kurobuta Pork, and more.'' No cap statement or creator count is published, so cap and saturation stay unknown.', 'verified', now());
  insert into public.brand_evidence (brand_id, source_url, source_type, evidence_type, evidence_summary, confidence, last_checked_at) values (bid, 'https://linkclicky.com/affiliate-program/snake-river-farms/', 'directory', 'affiliate', 'LinkClicky lists Snake River Farms on Impact at 10% per sale (''just what''s officially listed with their affiliate program''), corroborating the brand''s own page. Older listings (Lasso and ShareASale roundups) cite 7% with a 60-day cookie via ShareASale, which conflicts with the current own-page/Impact terms and is documented here as a superseded route.', 'publicly_reported', now());
  insert into public.brand_scores (brand_id, niche_fit, ugc_evidence, compensation, contact_access, opportunity_availability, credibility, explanation) values (bid, 25, 14, 13, 8, 9, 5, '{"niche_fit": "Premium Wagyu beef and pork are high-engagement content for grilling, BBQ and chef creators, with a reported ~$191\u2013200 average order value that makes 10% worth ~$19\u201320 per sale.", "ugc_evidence": "The brand''s own page explicitly recruits content creators and offers product review opportunities \u2014 direct evidence of a creator route, not just a publisher program.", "compensation": "10% commission on all sales published on the brand''s own page and corroborated by LinkClicky''s Impact listing; older 7% ShareASale reports are documented as superseded; no cap statement published.", "contact_access": "Dedicated affiliate managers are published on the brand''s own page, though no public partnerships email was found.", "opportunity_availability": "Quick open signup from the brand''s own page via Impact; approved affiliates ''can start earning commissions almost immediately'' per the page.", "credibility": "Heritage brand founded in 1968 (Agri Beef), featured on Michelin-starred menus per its own page, with terms published on its own domain."}'::jsonb);
  insert into public.brands (name, website, description, country, status) values ('ALOHA', 'https://aloha.com', 'Plant-based protein bars, drinks and powders brand. Its own ALOHA Collective page describes ''our affiliate program for people who genuinely love ALOHA'': members receive free products based on engagement and program activity, earn commission by sharing a unique affiliate link, and give followers an exclusive welcome offer. Applications run through the brand''s Superfiliate portal (alohaambassadors.superfiliate.com). The brand publishes no commission percentage on the page, so commission_rate is null. No cap statement or creator count is published, so cap and saturation are unknown.', 'United States', 'published') returning id into bid;
  insert into public.brand_categories (brand_id, category_id, is_primary) values (bid, (select id from public.categories where slug = 'food-drink'), true);
  insert into public.brand_contacts (brand_id, contact_type, email, contact_url, source_url, verification_status, last_verified_at) values (bid, 'creator_application', null, 'https://aloha.com/pages/aloha-collective', 'https://aloha.com/pages/aloha-collective', 'verified', now());
  insert into public.affiliate_programs (brand_id, network, commission_rate, commission_notes, application_url, status, last_checked_at) values (bid, 'Own program', null, 'Commission cap: not stated in any published source found — needs review. Creator saturation: unknown (see evidence). Rate as reported by https://aloha.com/pages/aloha-collective.', 'https://alohaambassadors.superfiliate.com', 'needs_review', now());
  insert into public.opportunities (brand_id, title, application_url, source_url, status, opportunity_type) values (bid, 'ALOHA Collective — the brand''s own affiliate program: free product by engagement, commission via unique link, follower welcome offer', 'https://alohaambassadors.superfiliate.com', 'https://aloha.com/pages/aloha-collective', 'unverified', 'ugc');
  insert into public.brand_evidence (brand_id, source_url, source_type, evidence_type, evidence_summary, confidence, last_checked_at) values (bid, 'https://aloha.com/pages/aloha-collective', 'official_site', 'affiliate', 'ALOHA''s own Collective page, fetched in full: ''Meet the ALOHA Collective—our affiliate program for people who genuinely love ALOHA and want to share it with their community.'' Perks listed: ''Receive FREE ALOHA products based on engagement and program activity,'' ''Earn commission by sharing a unique affiliate link,'' and an ''exclusive welcome offer'' for followers; approved members receive a welcome gift. Apply buttons route to alohaambassadors.superfiliate.com. No percentage rate, cap statement or creator count is published on the page, so the rate is null and cap/saturation stay unknown.', 'verified', now());
  insert into public.brand_scores (brand_id, niche_fit, ugc_evidence, compensation, contact_access, opportunity_availability, credibility, explanation) values (bid, 25, 15, 10, 8, 9, 5, '{"compensation": "Commission via unique affiliate link is published on the brand''s own page, but no percentage is stated anywhere fetched, so no rate is recorded; no cap statement published.", "contact_access": "Application runs through the brand''s own Superfiliate portal linked from its Collective page; no public partnerships email was found.", "credibility": "Established US plant-based food brand with program details published on its own domain.", "niche_fit": "Plant-based protein bars and drinks are everyday snack and wellness-routine content with broad creator appeal.", "opportunity_availability": "Open application on the brand''s own site; the page invites unsure applicants to apply anyway for routing to the best-fit track.", "ugc_evidence": "A named own-site affiliate program (the ALOHA Collective) with engagement-based free product and a welcome gift for approved members."}'::jsonb);
  insert into public.brands (name, website, description, country, status) values ('Ketone-IQ', 'https://ketone.com', 'Drinkable ketone shots (pure R-1,3-butanediol ketone diol) for focus and energy, from the company founded as HVMN and rebranded to Ketone-IQ in 2024; distributed nationwide in Target and Sprouts. AdvertiserReview''s keto program roundup reports a base commission of 10–15% CPS on one-time and recurring subscription sales, tracked via Impact / Refersion with a 30-day cookie, a $50 minimum payout and monthly Net-30 payments. Because the published figure is a range, commission_rate is null with the range documented. No cap statement or creator count is published, so cap and saturation are unknown.', 'United States', 'published') returning id into bid;
  insert into public.brand_categories (brand_id, category_id, is_primary) values (bid, (select id from public.categories where slug = 'wellness'), true);
  insert into public.brand_contacts (brand_id, contact_type, email, contact_url, source_url, verification_status, last_verified_at) values (bid, 'creator_application', null, 'https://advertiserreview.com/affiliate/programs/keto/', 'https://advertiserreview.com/affiliate/programs/keto/', 'needs_review', null);
