  insert into public.opportunities (brand_id, title, application_url, source_url, status, opportunity_type) values (bid, 'Ketone-IQ Affiliate Program — reported 10–15% CPS on one-time and subscription sales via Impact / Refersion (range; no single rate recorded)', 'https://advertiserreview.com/affiliate/programs/keto/', 'https://advertiserreview.com/affiliate/programs/keto/', 'unverified', 'ugc');
  insert into public.brand_evidence (brand_id, source_url, source_type, evidence_type, evidence_summary, confidence, last_checked_at) values (bid, 'https://advertiserreview.com/affiliate/programs/keto/', 'directory', 'affiliate', 'AdvertiserReview''s keto affiliate roundup entry for Ketone-IQ (by HVMN): base commission 10–15% CPS applying to both one-time purchases and recurring subscription sales, tracking via Impact / Refersion, 30-day cookie, $50 minimum payout, monthly payments on Net-30 terms. A range is not a settled single rate, so commission_rate is null with the range documented. No cap statement or creator count is published.', 'publicly_reported', now());
  insert into public.brand_scores (brand_id, niche_fit, ugc_evidence, compensation, contact_access, opportunity_availability, credibility, explanation) values (bid, 23, 11, 13, 6, 8, 4, '{"compensation": "A 10\u201315% CPS range on both one-time and recurring subscription sales is reported with a 30-day cookie \u2014 a range, so no single rate is recorded; no cap statement published.", "contact_access": "No public partnerships email was found on the fetched pages; application runs through the network listing.", "credibility": "Category-creating brand (first drinkable ketone, 2017) with nationwide Target and Sprouts distribution and a World Tour cycling partnership.", "niche_fit": "Ketone shots fit performance, focus and biohacking creator content, with a distinctive science-led story and premium pricing.", "opportunity_availability": "Open network application via Impact / Refersion as reported.", "ugc_evidence": "A network affiliate program covering creators and publishers is reported; no structured on-site creator community is published."}'::jsonb);
  insert into public.brands (name, website, description, country, status) values ('Grüns', 'https://gruns.co', 'Daily greens gummy supplement brand. Trade-press coverage of its agency (T-Bar Partners) documents a large TikTok Shop affiliate program: free samples with creative briefs, post-count contests with cash prizes, and retainers for top sellers. The brand''s own referral page separately pays a flat $20 for every referral plus product rewards via a personal link. No TikTok Shop percentage is published in the fetched sources, so commission_rate is null with the flat referral documented. No cap statement and no absolute creator count are published (coverage implies thousands of creator videos, which is scale, not low saturation), so cap and saturation are unknown.', 'United States', 'published') returning id into bid;
  insert into public.brand_categories (brand_id, category_id, is_primary) values (bid, (select id from public.categories where slug = 'wellness'), true);
  insert into public.brand_contacts (brand_id, contact_type, email, contact_url, source_url, verification_status, last_verified_at) values (bid, 'creator_application', null, 'https://gruns.co/pages/referrals', 'https://gruns.co/pages/referrals', 'verified', now());
  insert into public.affiliate_programs (brand_id, network, commission_rate, commission_notes, application_url, status, last_checked_at) values (bid, 'TikTok Shop', null, 'Commission cap: not stated in any published source found — needs review. Creator saturation: unknown (see evidence). Rate as reported by https://gruns.co/pages/referrals.', 'https://gruns.co/pages/referrals', 'needs_review', now());
  insert into public.opportunities (brand_id, title, application_url, source_url, status, opportunity_type) values (bid, 'Grüns TikTok Shop Affiliate Program (agency-run: samples, briefs, post-count contests, retainers) + own referral program paying a flat $20 per referral', 'https://gruns.co/pages/referrals', 'https://gruns.co/pages/referrals', 'unverified', 'ugc');
  insert into public.brand_evidence (brand_id, source_url, source_type, evidence_type, evidence_summary, confidence, last_checked_at) values (bid, 'https://gruns.co/pages/referrals', 'official_site', 'affiliate', 'Grüns'' own referral program page, fetched in full: ''Join the Grüns referral program! Earn product rewards and $20 for every single referral. It''s as easy as sharing your personal link!'' The page notes the program is ''designed for personal, unpaid referrals only'' and that paid-ad arbitrage commissions are not honored. The $20 is a flat per-referral amount, not a percentage, so commission_rate is null. No cap statement or creator count is published.', 'verified', now());
  insert into public.brand_evidence (brand_id, source_url, source_type, evidence_type, evidence_summary, confidence, last_checked_at) values (bid, 'https://theinfluencermarketingnews.com/news/tiktok-shop-affiliate-program-three-videos-per-sample/', 'directory', 'affiliate', 'Trade-press account of a Commerce Roundtable talk by T-Bar Partners, the agency running Grüns'' TikTok Shop affiliate program: creators receive free samples with a creative brief and Discord access, contests pay cash for post count (first place $3,000, second $2,000, plus a top-seller prize), and strong sellers are offered retainers; the agency describes shipping roughly 500 samples per month across its brands and aiming for at least three videos per sample. This documents an active, structured TikTok Shop creator program at scale — no commission percentage or absolute creator count for Grüns is published.', 'publicly_reported', now());
  insert into public.brand_scores (brand_id, niche_fit, ugc_evidence, compensation, contact_access, opportunity_availability, credibility, explanation) values (bid, 26, 18, 11, 7, 9, 5, '{"compensation": "The brand''s own referral page pays a flat $20 per referral plus product rewards; the TikTok Shop percentage is not published in the fetched sources, so no rate is recorded; no cap statement published.", "contact_access": "Join routes are the brand''s own referral page and TikTok Shop''s affiliate flow; no public partnerships email was found.", "credibility": "Fast-scaling brand reported to have reached roughly $300M annualized revenue within two years and acquired by Unilever, per trade coverage.", "niche_fit": "Greens gummies are highly demo-able daily-routine content, and Gr\u00fcns is one of the most visible supplement brands on TikTok Shop.", "opportunity_availability": "Open TikTok Shop affiliate enrollment plus an open own-site referral program.", "ugc_evidence": "An agency-run TikTok Shop affiliate engine with samples, monthly-refreshed briefs, cash contests and retainers is documented in trade press \u2014 among the strongest creator-program evidence in this batch."}'::jsonb);
  insert into public.brands (name, website, description, country, status) values ('Built Bar', 'https://built.com', 'Protein bars and Built Puffs brand. Its Built Ambassador Program is reported at 10% commission on all orders (with a 10% follower discount), with registration through the brand''s ambassador portal; Shopper.com''s 6.65% figure is EPC-derived and conflicts, so commission_rate is null with the conflict documented. The brand is also a major TikTok Shop seller, with a case study citing 710K+ units sold through creator affiliates. No cap statement or creator count is published, so cap and saturation are unknown.', 'United States', 'published') returning id into bid;
