  insert into public.brand_contacts (brand_id, contact_type, email, contact_url, source_url, verification_status, last_verified_at) values (bid, 'creator_application', null, 'https://brandambassadorapp.net/forms/register/builtbar', 'https://linkwhisper.com/keto-affiliate-programs/', 'needs_review', null);
  insert into public.affiliate_programs (brand_id, network, commission_rate, commission_notes, application_url, status, last_checked_at) values (bid, 'Own program', null, 'Commission cap: not stated in any published source found — needs review. Creator saturation: unknown (see evidence). Rate as reported by https://linkwhisper.com/keto-affiliate-programs/.', 'https://brandambassadorapp.net/forms/register/builtbar', 'needs_review', now());
  insert into public.opportunities (brand_id, title, application_url, source_url, status, opportunity_type) values (bid, 'Built Ambassador Program — reported 10% on all orders via the brand''s ambassador portal (rate unsettled; see evidence); large TikTok Shop affiliate presence', 'https://brandambassadorapp.net/forms/register/builtbar', 'https://linkwhisper.com/keto-affiliate-programs/', 'unverified', 'ugc');
  insert into public.brand_evidence (brand_id, source_url, source_type, evidence_type, evidence_summary, confidence, last_checked_at) values (bid, 'https://linkwhisper.com/keto-affiliate-programs/', 'directory', 'affiliate', 'LinkWhisper''s keto affiliate roundup entry for Built Bar: the official program name is the Built Ambassador Program, commission rate 10% on all orders, affiliates also receive a 10% discount, and registration runs through brandambassadorapp.net/forms/register/builtbar. No cap statement or creator count is published.', 'publicly_reported', now());
  insert into public.brand_evidence (brand_id, source_url, source_type, evidence_type, evidence_summary, confidence, last_checked_at) values (bid, 'https://www.shopper.com/partnerships/builtbar-com-affiliate-program', 'directory', 'affiliate', 'Shopper.com''s Built Bar listing states a 6.65% payout, an EPC-derived figure that conflicts with the 10% ambassador rate reported by LinkWhisper, so commission_rate is null with the conflict documented. A separate creator case study of Built''s TikTok Shop engine cites 710.1K units sold and hundreds of creators posting organically for commission only, evidencing a large TikTok Shop affiliate route.', 'publicly_reported', now());
  insert into public.brand_scores (brand_id, niche_fit, ugc_evidence, compensation, contact_access, opportunity_availability, credibility, explanation) values (bid, 25, 15, 11, 8, 9, 5, '{"compensation": "10% on all orders is reported for the ambassador program, but Shopper''s EPC-derived 6.65% conflicts, so no rate is recorded; no cap statement published.", "contact_access": "A direct public registration form for the ambassador program is published; no public partnerships email was found.", "credibility": "Established national protein-snack brand sold widely in US retail with program details reported across directories.", "niche_fit": "Candy-like protein bars and puffs are proven taste-test and snack-swap content for fitness and food creators, with many flavors to rotate.", "opportunity_availability": "Open registration for the ambassador program, plus open TikTok Shop affiliate enrollment.", "ugc_evidence": "A named ambassador program plus a documented TikTok Shop creator engine (hundreds of creators, 710K+ units sold per a case study)."}'::jsonb);
  insert into public.brands (name, website, description, country, status) values ('Vega', 'https://myvega.com', 'Plant-based protein and nutrition brand. Its own US affiliates page states the Vega Affiliate Program is managed through Awin, pays a competitive tiered commission on all referred eStore sales (including repeat tracked purchases for up to 60 days), cites an average order size over $80, offers a dedicated affiliate manager, and publishes the manager''s email, affiliates@myvega.com. The brand''s page publishes no percentage, and third-party reports conflict (5% via ShareASale historically, 8–15% per Lasso, 2–10% via CJ historically), so commission_rate is null with the conflict documented. No cap statement or creator count is published, so cap and saturation are unknown.', 'United States', 'published') returning id into bid;
  insert into public.brand_categories (brand_id, category_id, is_primary) values (bid, (select id from public.categories where slug = 'wellness'), true);
  insert into public.brand_contacts (brand_id, contact_type, email, contact_url, source_url, verification_status, last_verified_at) values (bid, 'partnerships', 'affiliates@myvega.com', 'http://myvega.com/pages/affiliates', 'http://myvega.com/pages/affiliates', 'verified', now());
  insert into public.affiliate_programs (brand_id, network, commission_rate, commission_notes, application_url, status, last_checked_at) values (bid, 'Awin', null, 'Commission cap: not stated in any published source found — needs review. Creator saturation: unknown (see evidence). Rate as reported by http://myvega.com/pages/affiliates.', 'http://myvega.com/pages/affiliates', 'needs_review', now());
  insert into public.opportunities (brand_id, title, application_url, source_url, status, opportunity_type) values (bid, 'Vega Affiliate Program — tiered commissions via Awin with a dedicated affiliate manager (brand publishes no percentage; rate unsettled)', 'http://myvega.com/pages/affiliates', 'http://myvega.com/pages/affiliates', 'unverified', 'ugc');
  insert into public.brand_evidence (brand_id, source_url, source_type, evidence_type, evidence_summary, confidence, last_checked_at) values (bid, 'http://myvega.com/pages/affiliates', 'official_site', 'affiliate', 'Vega''s own US affiliates page, fetched in full: ''The VEGA Affiliate Program is managed through Awin program software''; affiliates ''earn a commission on all sales that are referred to the VEGA eStore,'' including ''any subsequent tracked purchases that a customer makes for up to 60 days''; ''Competitive, tiered commission structure''; average order size of $78 (body text says over $80); ''Dedicated affiliate manager''; and ''contact our affiliate program manager at affiliates@myvega.com.'' The page publishes no percentage rate, cap statement or creator count.', 'verified', now());
  insert into public.brand_evidence (brand_id, source_url, source_type, evidence_type, evidence_summary, confidence, last_checked_at) values (bid, 'https://getlasso.co/affiliate/vega/', 'directory', 'affiliate', 'Lasso lists the Vega program at 8–15% per sale with a 7-day cookie, while a protein-powder roundup reports 5% via ShareASale (60-day cookie) and an older directory reports 2–10% via Commission Junction — three conflicting network/rate accounts against the brand''s current own-page Awin statement, so commission_rate is null with the conflict documented and Awin recorded as the current network per the brand.', 'publicly_reported', now());
  insert into public.brand_scores (brand_id, niche_fit, ugc_evidence, compensation, contact_access, opportunity_availability, credibility, explanation) values (bid, 25, 12, 11, 13, 9, 5, '{"compensation": "The brand publishes only a ''competitive, tiered'' structure with repeat-purchase tracking up to 60 days and a ~$78\u201380 average order; third-party rates conflict (5% / 8\u201315% / 2\u201310%), so no rate is recorded; no cap statement published.", "contact_access": "The affiliate program manager''s email, affiliates@myvega.com, is published on the brand''s own page, and a dedicated manager is offered \u2014 the strongest contact access in this batch.", "credibility": "Long-established plant-based nutrition brand with program terms published on its own domain.", "niche_fit": "Plant-based protein is foundational fitness and vegan-lifestyle content, and Vega is one of the category''s most recognized names.", "opportunity_availability": "Open application through Awin from the brand''s own affiliates page, with quick review promised.", "ugc_evidence": "A long-running network affiliate program aimed at health, fitness and nutrition sites; no structured creator community is published."}'::jsonb);
  insert into public.brands (name, website, description, country, status) values ('Kalm with Kava', 'https://kalmwithkava.com', 'Noble kava root drinks and powders sourced directly from small South Pacific farmers, founded in 2010 and sold for relaxation and stress relief. Awin''s merchant profile for the program (listed under Monsoon Beverages) publishes a 10% commission on every referred sale, a 90-day cookie and an average order value around $90. No cap statement or creator count is published, so cap and saturation are unknown.', 'United States', 'published') returning id into bid;
  insert into public.brand_categories (brand_id, category_id, is_primary) values (bid, (select id from public.categories where slug = 'food-drink'), true);
  insert into public.brand_contacts (brand_id, contact_type, email, contact_url, source_url, verification_status, last_verified_at) values (bid, 'creator_application', null, 'https://ui.awin.com/merchant-profile/75634?setLocale=da_DK', 'https://ui.awin.com/merchant-profile/75634?setLocale=da_DK', 'needs_review', null);
