  insert into public.brand_evidence (brand_id, source_url, source_type, evidence_type, evidence_summary, confidence, last_checked_at) values (bid, 'https://ui.awin.com/merchant-profile/75634?setLocale=da_DK', 'directory', 'affiliate', 'Awin''s merchant profile for the Monsoon Beverages / Kalm with Kava Affiliate Program: ''Generous Commissions: Earn a lucrative 10% commission on every sale you refer,'' attribution period (cookie length) 90 days, and an average order value of around $90, with marketing materials and personalized support offered. No cap statement or creator count is published.', 'publicly_reported', now());
  insert into public.brand_scores (brand_id, niche_fit, ugc_evidence, compensation, contact_access, opportunity_availability, credibility, explanation) values (bid, 21, 9, 13, 6, 8, 4, '{"compensation": "10% commission published on Awin''s own merchant profile, with a long 90-day cookie and ~$90 average order value; no cap statement published.", "contact_access": "No public partnerships email was found; application and contact run through Awin.", "credibility": "Specialist kava vendor operating since 2010, selling only certified Noble kava sourced from Pacific Island farmers.", "niche_fit": "Kava is a niche but growing alcohol-alternative relaxation ritual with a devoted community \u2014 strong fit for a smaller set of wellness creators.", "opportunity_availability": "Open application via Awin''s merchant program.", "ugc_evidence": "A standard network affiliate program with marketing materials and support; no structured creator community is published."}'::jsonb);
  insert into public.brands (name, website, description, country, status) values ('PUR Cold-Pressed', 'https://purcoldpressed.com', 'Fresh cold-pressed juice brand (juice cleanses and daily juices; 40,000+ orders and 5,000+ members claimed on its own page). Its own affiliate page publishes ''Earn 10% on eligible sales'' for partners who share through websites and social channels, with signup routed to Refersion (refr.cc). A separate creators/collabs page offers ambassador partnerships spanning affiliate commission, gifting and discount codes. No cap statement or creator count is published, so cap and saturation are unknown.', 'United States', 'published') returning id into bid;
  insert into public.brand_categories (brand_id, category_id, is_primary) values (bid, (select id from public.categories where slug = 'food-drink'), true);
  insert into public.brand_contacts (brand_id, contact_type, email, contact_url, source_url, verification_status, last_verified_at) values (bid, 'creator_application', null, 'https://purcoldpressed.com/pages/affiliate', 'https://purcoldpressed.com/pages/affiliate', 'verified', now());
  insert into public.affiliate_programs (brand_id, network, commission_rate, commission_notes, application_url, status, last_checked_at) values (bid, 'Refersion', 10, 'Commission cap: not stated in any published source found — needs review. Creator saturation: unknown (see evidence). Rate as reported by https://purcoldpressed.com/pages/affiliate.', 'https://purcoldpressed.com/pages/affiliate', 'needs_review', now());
  insert into public.opportunities (brand_id, title, application_url, source_url, status, opportunity_type) values (bid, 'PUR Cold-Pressed Affiliate Program — 10% on eligible sales via Refersion, plus a creator collabs/ambassador route', 'https://purcoldpressed.com/pages/affiliate', 'https://purcoldpressed.com/pages/affiliate', 'unverified', 'ugc');
  insert into public.brand_evidence (brand_id, source_url, source_type, evidence_type, evidence_summary, confidence, last_checked_at) values (bid, 'https://purcoldpressed.com/pages/affiliate', 'official_site', 'affiliate', 'PUR''s own affiliate page, fetched in full: ''Join our cold-pressed juice affiliate program to share products you love with your wellness audience. Earn 10% on eligible sales by introducing more people to PUR Cold Pressed Juice through your website and social channels.'' Signup buttons route to purcoldpressedjuic.refr.cc, Refersion''s domain, confirming the Refersion platform. The page claims 40,000+ orders placed, 5,000+ members and 4.9/5 from 3,200+ reviews. No cap statement or creator count is published.', 'verified', now());
  insert into public.brand_evidence (brand_id, source_url, source_type, evidence_type, evidence_summary, confidence, last_checked_at) values (bid, 'https://purcoldpressed.com/pages/creators', 'official_site', 'affiliate', 'The brand''s own Collabs page invites creators to ''Become an ambassador'' and lists partnership opportunities: affiliate marketing, gifting, discount codes and additional opportunities — ''We offer affiliate commission, our collaborators LOVE our brand.'' This documents a creator-facing route alongside the affiliate program.', 'publicly_reported', now());
  insert into public.brand_scores (brand_id, niche_fit, ugc_evidence, compensation, contact_access, opportunity_availability, credibility, explanation) values (bid, 23, 13, 13, 7, 9, 4, '{"niche_fit": "Cold-pressed juices and cleanses are visual, routine-friendly wellness content for health and reset-focused creators.", "ugc_evidence": "An own-site affiliate program plus a dedicated creators/collabs page recruiting ambassadors with affiliate commission and discount codes.", "compensation": "10% on eligible sales published on the brand''s own affiliate page; no cap statement published.", "contact_access": "Application runs through the brand''s own page into Refersion; no public partnerships email was found.", "opportunity_availability": "Open application from the brand''s own affiliate page.", "credibility": "Operating DTC juice brand claiming 40,000+ orders and 4.9/5 across 3,200+ reviews on its own page, with terms published on its own domain."}'::jsonb);
