  insert into public.brand_scores (brand_id, niche_fit, ugc_evidence, compensation, contact_access, opportunity_availability, credibility, explanation) values (bid, 23, 11, 19, 7, 8, 3, '{"niche_fit": "Home air-quality and germ-conscious cleaning content is an established home-creator niche, and purifiers demo visibly (dust, odors, filter changes).", "ugc_evidence": "The program listing is written for bloggers and influencers, but the brand publishes no creator program page of its own that was fetched.", "compensation": "A published 25% per sale with a 30-day cookie is the strongest rate in this batch, on premium-priced purification hardware.", "contact_access": "Application route is documented through the program''s CJ listing; no public partnerships email was found on a fetched page.", "opportunity_availability": "Program is live and joinable now through CJ, per the listing''s sign-up route.", "credibility": "Operating DTC purification brand with a live network program; smaller and less widely retailed than the batch''s big-name brands."}'::jsonb);
