  insert into public.brand_scores (brand_id, niche_fit, ugc_evidence, compensation, contact_access, opportunity_availability, credibility, explanation) values (bid, 24, 13, 13, 7, 8, 4, '{"niche_fit": "A phone-controlled scent diffuser is highly demonstrable smart-home content \u2014 scent swaps, schedules and room tours are proven home-creator formats.", "ugc_evidence": "The program runs on Impact, a creator-recruiting network, and the profile is written for publishers and influencers; Pura is also a familiar brand in influencer home content.", "compensation": "Published 8%-15% per sale; recorded at the 8% floor. The range''s top end is attractive, but no cookie duration is published.", "contact_access": "Application route is documented through the program''s Impact listing; no public creator contact email was found on a fetched page.", "opportunity_availability": "Program is live and joinable now through Impact.", "credibility": "Well-known DTC smart-fragrance brand with mass influencer awareness and national retail presence."}'::jsonb);
