  insert into public.brand_scores (brand_id, niche_fit, ugc_evidence, compensation, contact_access, opportunity_availability, credibility, explanation) values (bid, 25, 12, 11, 7, 8, 5, '{"niche_fit": "Device skins and cases are core tech-creator content \u2014 installs, teardowns and desk setups film in seconds and refresh with every device launch.", "ugc_evidence": "The program is listed for tech bloggers and influencers on two directories; dbrand''s brand is built on creator and social culture, though no dedicated creator page was fetched.", "compensation": "Published 7% per sale with a 30-day cookie, corroborated by two independent listings; a mid-range accessories rate.", "contact_access": "Application route is documented through the CJ listing; no public partnerships email was found on a fetched page.", "opportunity_availability": "Program is live and joinable now through CJ.", "credibility": "Category-defining device-skin brand with a decade-plus track record and a long-running network program."}'::jsonb);
  insert into public.brands (name, website, description, country, status) values ('Bully Beds', 'https://bullybeds.com', 'Premium dog-bed brand built for large and giant breeds: orthopedic memory-foam beds with washable, chew-resistant microfiber covers and long warranties. Its affiliate program runs on ShareASale with a published 6% commission per sale and a 30-day cookie.', 'United States', 'published') returning id into bid;
