  insert into public.brand_scores (brand_id, niche_fit, ugc_evidence, compensation, contact_access, opportunity_availability, credibility, explanation) values (bid, 24, 11, 11, 7, 8, 4, '{"niche_fit": "Big-dog comfort is a loyal pet niche; orthopedic beds for giant breeds demo well in dog-home and senior-dog content.", "ugc_evidence": "The program listing addresses pet bloggers and influencers; no brand-run creator page was fetched.", "compensation": "Published 6% per sale with a 30-day cookie; beds are premium-priced, so per-sale payouts are meaningful despite the modest percentage.", "contact_access": "Application route is documented through the program listing into ShareASale; no public creator email was found on a fetched page.", "opportunity_availability": "Program is live and joinable now through ShareASale.", "credibility": "Established specialist DTC brand with long warranties and a long-running affiliate presence."}'::jsonb);
