  insert into public.brand_evidence (brand_id, source_url, source_type, evidence_type, evidence_summary, confidence, last_checked_at) values (bid, 'https://www.shopper.com/partnerships/u-tec-com-affiliate-program', 'third_party', 'affiliate', 'Shopper.com''s Ultraloq (U-tec) US listing reports a 10% payout per sale with a 1-month cookie, and the brand''s own Instagram creator-program post advertises 15% commission on approved creator sales. Because published rates conflict across fetched sources (5% / 10% / 15%), commission_rate is recorded as null; the ShareASale route and the existence of a brand creator program are the consistent facts.', 'publicly_reported', now());
