  insert into public.brand_evidence (brand_id, source_url, source_type, evidence_type, evidence_summary, confidence, last_checked_at) values (bid, 'https://www.creator-hero.com/blog/gopro-affiliate-program-in-depth-review-pros-and-cons', 'third_party', 'affiliate', 'Creator Hero''s in-depth GoPro program review (published Nov 2024, updated May 2026; fetched in full for this batch): GoPro runs its affiliate program exclusively through the Partnerize network at 3% per sale with a 30-day cookie, global availability, and sign-up via GoPro''s official affiliate page (gopro.com/en/us/legal/gopro-affiliate-program), with manual brand-fit review. A second directory (UpPromote) independently reports the same Partnerize management and 3% flat rate. No earnings-cap statement and no creator count are published, so cap and saturation stay unknown.', 'publicly_reported', now());
  insert into public.brand_evidence (brand_id, source_url, source_type, evidence_type, evidence_summary, confidence, last_checked_at) values (bid, 'https://getlasso.co/affiliate/gopro/', 'third_party', 'affiliate', 'Lasso''s GoPro program listing instead reports the program on Impact at 4% per sale with a 7-day cookie. Because the network and rate conflict with the Partnerize / 3% / 30-day terms reported by two other fetched sources, commission_rate is recorded as null and the conflict is documented here.', 'publicly_reported', now());
  insert into public.brand_scores (brand_id, niche_fit, ugc_evidence, compensation, contact_access, opportunity_availability, credibility, explanation) values (bid, 26, 13, 6, 7, 7, 5, '{"niche_fit": "Action cameras are creator tools first \u2014 travel, sports and POV content is the product''s native habitat, and every launch is a content event.", "ugc_evidence": "The program is documented across multiple creator-focused directories and GoPro''s brand is built on user-generated footage, though approval is a manual brand-fit review.", "compensation": "No rate can be honestly recorded: two fetched sources report 3% via Partnerize while Lasso reports 4% via Impact.", "contact_access": "Sign-up runs from GoPro''s own affiliate page into the network, as documented by the fetched review; no public partnerships email was found.", "opportunity_availability": "Program is live globally, but applications are manually reviewed for brand fit, which narrows instant availability.", "credibility": "Category-defining public camera brand with over $1B in reported 2024 revenue."}'::jsonb);
